'use strict';const fs=require('fs'),{db}=require('./db');require('./referenceLibrary');
if(!db.prepare("SELECT value FROM settings WHERE key='generation_guard_defaults_v1'").get()){db.transaction(()=>{for(const [key,value]of [['retry_count','0'],['paste_auto_run','0'],['generation_guard_defaults_v1','1']])db.prepare('INSERT OR REPLACE INTO settings(key,value) VALUES(?,?)').run(key,value)})()}
const mentionTags=text=>[...new Set([...String(text).matchAll(/(?:^|[\s(])@([\p{L}\p{N}_-]+)/gu)].map(m=>m[1].toLowerCase()))];
function inspectGeneration(body={},options={}){const errors=[],warnings=[];try{body=require('./videoReferences.cjs').normalizeVideoBody(body)}catch(e){return {valid:false,errors:[e.message],warnings:[]}};const prompts=Array.isArray(body.prompts)?body.prompts.map(x=>typeof x==='string'?x.trim():''):typeof body.prompts==='string'?[body.prompts.trim()]:[];const media=body.mediaType==='image'?'image':'video',ratio=body.ratio||'9:16',duration=Number(body.duration??10),refs=Array.isArray(body.refTags)?body.refTags:body.batchRefImage?[body.batchRefImage]:[];if(body.mediaType&&!['image','video'].includes(body.mediaType))errors.push('Loại tác vụ không hợp lệ');if(body.refTags!==undefined&&!Array.isArray(body.refTags))errors.push('Ảnh tham chiếu phải là danh sách');if(!prompts.length||prompts.some(p=>!p))errors.push('Prompt không được để trống');if(media==='image'&&prompts.length>30)errors.push('Mỗi bộ tạo tối đa 30 ảnh');if(prompts.length>100)errors.push('Mỗi lần thêm tối đa 100 prompt');if(!(media==='video'?['9:16','16:9','1:1']:['9:16','16:9','1:1','4:3','3:4']).includes(ratio))errors.push('Tỉ lệ không được hỗ trợ');if(media==='video'&&![3,5,7,8,10].includes(duration))errors.push('Video hỗ trợ 3, 5, 7, 8 hoặc 10 giây');const seen=new Set();prompts.forEach((prompt,i)=>{if(require('./faceSwapContract.cjs').isFaceSwap(prompt)){try{require('./faceSwapContract.cjs').faceSwapManifest(prompt,refs.map(tag=>({tag:String(tag).replace(/^@/,'')})))}catch(e){errors.push(e.message)}}if(String(prompt).startsWith('BATCH VISUAL RECREATION.')){try{require('./conceptContract.cjs').conceptManifest(prompt,refs.map(tag=>({tag:String(tag).replace(/^@/,'')})))}catch(e){errors.push(e.message)}}const label=prompts.length>1?'Prompt '+(i+1)+': ':'';if(prompt.length>20000)errors.push(label+'Nội dung vượt 20.000 ký tự');else if(prompt.length>6000)warnings.push(label+'Prompt rất dài; nên tập trung vào một cảnh để giảm yêu cầu xung đột.');if(/\[(?:BRAND NAME|PRODUCT NAME|INSERT[^\]]*|TÊN[^\]]*|YOUR[^\]]*)\]|\{\{[^}]+\}\}/i.test(prompt))warnings.push(label+'Còn placeholder chưa điền. Kiểm tra tên sản phẩm/nội dung mẫu.');const ratios=[...new Set(prompt.match(/\b(?:9:16|16:9|1:1|4:3|3:4)\b/g)||[])];if(ratios.some(r=>r!==ratio))warnings.push(label+'Tỉ lệ trong prompt khác thiết lập '+ratio+'.');if(media==='video'){const secs=[...prompt.matchAll(/\b(5|10|15)[ -]?(?:giây|seconds?|secs?|s\b)/gi)].map(m=>Number(m[1]));if(secs.some(s=>s!==duration))warnings.push(label+'Thời lượng trong prompt khác thiết lập '+duration+' giây.')}const tags=[...new Set([...refs.map(String).map(t=>t.replace(/^@/,'').toLowerCase()),...mentionTags(prompt)])];if(tags.length>(media==='video'?5:4))errors.push(label+'Tối đa '+(media==='video'?5:4)+' ảnh tham chiếu cho mỗi tác vụ');for(const tag of tags){if(seen.has(tag))continue;seen.add(tag);const ref=db.prepare('SELECT * FROM ref_images WHERE lower(tag)=?').get(tag);if(!ref||(ref.archived_at&&!options.allowArchived)){errors.push('Ảnh @'+tag+' không có trong thư viện hoặc đang ở thùng rác');continue}if(!fs.existsSync(ref.filepath)){errors.push('File ảnh @'+tag+' đã mất trên máy');continue}const stat=fs.statSync(ref.filepath);if(stat.size>8*1024*1024)errors.push('Ảnh @'+tag+' vượt 8 MB; xuất bản nhỏ hơn trước khi dùng');if(!/\.(png|jpe?g|webp)$/i.test(ref.filename))errors.push('Ảnh @'+tag+' phải là PNG, JPG hoặc WebP');const fd=fs.openSync(ref.filepath,'r'),head=Buffer.alloc(12);try{fs.readSync(fd,head,0,12,0)}finally{fs.closeSync(fd)}if(!(head.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]))||head[0]===255&&head[1]===216||head.subarray(0,4).toString()==='RIFF'&&head.subarray(8,12).toString()==='WEBP'))errors.push('File ảnh @'+tag+' bị hỏng hoặc sai định dạng');if(ref.role==='character_full'&&/(thay|đổi|change|replace).{0,30}(trang phục|quần áo|outfit|clothing)/i.test(prompt))warnings.push('Ảnh @'+tag+' đang khóa toàn thân/trang phục; dùng Ảnh nhanh → Thay trang phục để tách đúng vai trò.')}});return {valid:errors.length===0,errors:[...new Set(errors)],warnings:[...new Set(warnings)],promptCount:prompts.length,mediaType:media}}
module.exports={inspectGeneration,mentionTags};
